#:property PublishAot=false

// Find the earliest Friday the 13th in the proleptic Gregorian calendar (from 0001-01-01)
// and count how many occur in a full 400-year cycle.

DateTime? earliest = null;
int count400 = 0;

for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            earliest ??= d;
            count400++;
        }
    }
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest:dddd})");
Console.WriteLine($"Friday the 13ths in a 400-year cycle (0001–0400): {count400}");
Console.WriteLine($"Average per year: {count400 / 400.0:F4}");

// Bonus: distribution by month
var byMonth = new int[13];
for (int year = 1; year <= 400; year++)
    for (int month = 1; month <= 12; month++)
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            byMonth[month]++;

Console.WriteLine("\nDistribution by month (400-year cycle):");
for (int m = 1; m <= 12; m++)
    Console.WriteLine($"  {new DateTime(2000, m, 1):MMMM,-12} {byMonth[m]}");

